package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertJobRecords.*;import static org.junit.jupiter.api.Assertions.*;
import java.time.*;import java.util.*;import java.net.*;import java.util.concurrent.atomic.AtomicReference;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.Test;
class AlertTaskClientTest {
 final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 Claim claim(String stage){return new Claim(UUID.randomUUID(),UUID.randomUUID(),stage,new Input(UUID.randomUUID(),4,"SH600030",LocalDate.of(2026,10,9),UUID.randomUUID(),"round1"),stage.equals("EVALUATE_RULE")?UUID.randomUUID():null,Instant.parse("2026-10-10T08:02:00Z"));}
 @Test void exactPathsTokensPayloadsAndSeparateStageReceipts()throws Exception{var body=new AtomicReference<JsonNode>();var path=new AtomicReference<String>();var response=new AtomicReference<String>();var token=new AtomicReference<String>();var method=new AtomicReference<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{path.set(ex.getRequestURI().getPath());method.set(ex.getRequestMethod());token.set(ex.getRequestHeaders().getFirst("X-Service-Token"));var bytes=ex.getRequestBody().readAllBytes();body.set(bytes.length==0?null:mapper.readTree(bytes));var out=response.get().getBytes();ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper);var c=claim("PREPARE_EVIDENCE");var evidence=UUID.randomUUID();response.set(receipt(c,"AVAILABLE","evidenceId",evidence,null));assertEquals(evidence,client.prepare(c).referenceId());assertEquals("/internal/v1/market/alert-evidence/prepare",path.get());assertEquals("private",token.get());assertEquals(Set.of("operationId","instrumentId","rawVersionId","tradeDate","leaseUntil"),keys(body.get()));assertEquals(c.input().rawVersionId().toString(),body.get().path("rawVersionId").asText());assertEquals(c.leaseUntil().toString(),body.get().path("leaseUntil").asText());client.receipt(c);assertEquals("GET",method.get());assertEquals("/internal/v1/market/alert-evidence/operations/"+c.attemptId(),path.get());var e=claim("EVALUATE_RULE");var trigger=UUID.randomUUID();response.set(receipt(e,"TRIGGERED","triggerId",trigger,null));assertEquals(trigger,client.evaluate(e).referenceId());assertEquals("/internal/v1/alert-evaluations",path.get());assertEquals(Set.of("operationId","ruleId","revision","evidenceId","leaseUntil"),keys(body.get()));assertEquals(4,body.get().path("revision").asLong());assertEquals(e.evidenceId().toString(),body.get().path("evidenceId").asText());client.receipt(e);assertEquals("/internal/v1/alert-evaluations/operations/"+e.attemptId(),path.get());}finally{server.stop(0);}}
 @Test void receipt404IsDistinctFromOtherFailures()throws Exception{for(String mode:List.of("missing","unauthorized","unavailable","invalid404")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{ex.getRequestBody().readAllBytes();byte[] out=(mode.equals("invalid404")?"not-json":"{\"code\":\"RESOURCE_NOT_FOUND\",\"data\":null}").getBytes();ex.sendResponseHeaders(mode.equals("unauthorized")?401:mode.equals("unavailable")?503:404,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper);var error=assertThrows(RuntimeException.class,()->client.receipt(claim("PREPARE_EVIDENCE")));assertEquals(mode.equals("missing"),error instanceof AlertTaskClient.MissingReceipt);assertFalse(assertThrows(RuntimeException.class,()->client.prepare(claim("PREPARE_EVIDENCE"))) instanceof AlertTaskClient.MissingReceipt);}finally{server.stop(0);}}}
 @Test void wrongIdsInvalidStatesRedirectsHugeAndSlowBodiesCannotSucceed()throws Exception{for(String mode:List.of("wrong","shortuuid","unknown","reference","missing-field","oversize","redirect","slow")){var c=claim("PREPARE_EVIDENCE");var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{ex.getRequestBody().readAllBytes();if(mode.equals("redirect")){ex.getResponseHeaders().set("Location","/elsewhere");ex.sendResponseHeaders(302,-1);}else if(mode.equals("slow")){ex.sendResponseHeaders(200,0);ex.getResponseBody().write('{');ex.getResponseBody().flush();try{Thread.sleep(1800);}catch(InterruptedException e){Thread.currentThread().interrupt();}}else{String s=receipt(c,"AVAILABLE","evidenceId",UUID.randomUUID(),null);if(mode.equals("wrong"))s=s.replace(c.attemptId().toString(),UUID.randomUUID().toString());if(mode.equals("shortuuid"))s=s.replace(c.attemptId().toString(),"1-1-1-1-1");if(mode.equals("unknown"))s=s.replace("AVAILABLE","FUTURE_STATE");if(mode.equals("reference"))s=receipt(c,"RUNNING","evidenceId",UUID.randomUUID(),null);if(mode.equals("missing-field"))s="{\"code\":\"OK\",\"data\":{\"operationId\":\""+c.attemptId()+"\",\"state\":\"RUNNING\"}}";if(mode.equals("oversize"))s="x".repeat(131073);var out=s.getBytes();ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);}ex.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper,Duration.ofMillis(300),Duration.ofMillis(300));long start=System.nanoTime();assertThrows(RuntimeException.class,()->client.prepare(c),mode);assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500,mode);}finally{server.stop(0);}}}
 @Test void evaluationStatesAndReasonsAreValidated()throws Exception{for(String state:List.of("NOT_MET","SKIPPED_RULE_CHANGED","SKIPPED_INACTIVE","SKIPPED_NOT_EFFECTIVE","SKIPPED_STALE","EVIDENCE_UNAVAILABLE","FAILED")){var c=claim("EVALUATE_RULE");var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{ex.getRequestBody().readAllBytes();var out=receipt(c,state,"triggerId",null,Set.of("FAILED","EVIDENCE_UNAVAILABLE").contains(state)?"SOURCE_UNAVAILABLE":state.equals("SKIPPED_INACTIVE")?"ACCOUNT_DISABLED":null).getBytes();ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();assertEquals(state,new HttpAlertTaskClient(base,base,"private",mapper).evaluate(c).state());}finally{server.stop(0);}}}
 @Test void actualMarketStaleReasonIsAcceptedForExecuteAndRecovery()throws Exception{var c=claim("PREPARE_EVIDENCE");var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",ex->{ex.getRequestBody().readAllBytes();var out=receipt(c,"SKIPPED_STALE","evidenceId",null,"ALERT_DATE_NOT_LATEST").getBytes();ex.sendResponseHeaders(200,out.length);ex.getResponseBody().write(out);ex.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper);assertEquals("SKIPPED_STALE",client.prepare(c).state());assertEquals("ALERT_DATE_NOT_LATEST",client.receipt(c).errorCode());}finally{server.stop(0);}}
 String receipt(Claim c,String state,String ref,UUID id,String error)throws com.fasterxml.jackson.core.JsonProcessingException{var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data").put("operationId",c.attemptId().toString()).put("state",state);if(id==null)d.putNull(ref);else d.put(ref,id.toString());if(error==null)d.putNull(c.stage().equals("PREPARE_EVIDENCE")?"errorCode":"reasonCode");else d.put(c.stage().equals("PREPARE_EVIDENCE")?"errorCode":"reasonCode",error);return mapper.writeValueAsString(n);}
 Set<String> keys(JsonNode n){var set=new HashSet<String>();n.fieldNames().forEachRemaining(set::add);return set;}
 @Test void knownLifecycleRejectionFailsExecutionButReadDoesNotInventReceipt()throws Exception{var calls=new java.util.concurrent.atomic.AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();e.getRequestBody().readAllBytes();byte[] out="{\"code\":\"MARKET_USE_NOT_READY\",\"data\":null}".getBytes();e.sendResponseHeaders(503,out.length);e.getResponseBody().write(out);e.close();});server.start();try{var base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper);var prepare=claim("PREPARE_EVIDENCE");assertEquals("FAILED",client.prepare(prepare).state());assertEquals("MARKET_USE_NOT_READY",client.evaluate(claim("EVALUATE_RULE")).errorCode());assertThrows(RuntimeException.class,()->client.receipt(prepare));assertEquals(3,calls.get());}finally{server.stop(0);}}

 @Test void ambiguousLifecycleErrorJsonMustNotBecomeTerminal()throws Exception{for(var body:List.of("{\"code\":\"MARKET_USE_UNAVAILABLE\",\"code\":\"MARKET_VERSION_USE_BLOCKED\",\"data\":null}","{\"code\":\"MARKET_VERSION_USE_BLOCKED\",\"data\":null} {}")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{e.getRequestBody().readAllBytes();var out=body.getBytes();e.sendResponseHeaders(409,out.length);e.getResponseBody().write(out);e.close();});server.start();try{String base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpAlertTaskClient(base,base,"private",mapper);assertThrows(RuntimeException.class,()->client.prepare(claim("PREPARE_EVIDENCE")));assertThrows(RuntimeException.class,()->client.evaluate(claim("EVALUATE_RULE")));}finally{server.stop(0);}}}

}
